def trim_context_without_llm(history, max_tool_output_chars=800, max_log_repeats=3):
    """零模型调用的确定性上下文裁剪，作为摘要之外的轻量前置步骤"""
    seen_errors = {}
    trimmed = []

    for turn in history:
        # 1. 工具结果清理：已被后续对话消费过的历史工具原始输出直接丢弃，只留一句引用
        if turn["type"] == "tool_result" and turn.get("consumed"):
            trimmed.append({"type": "tool_result_ref", "summary": turn["summary"]})
            continue

        # 2. 日志/报错去重聚合：相同错误只保留一条并记录出现次数
        if turn["type"] == "error_log":
            key = turn["error_signature"]
            seen_errors[key] = seen_errors.get(key, 0) + 1
            if seen_errors[key] > max_log_repeats:
                continue  # 超过阈值的重复报错不再重复携带
            turn = {**turn, "count": seen_errors[key]}

        # 3. 超长输出截断：只保留头尾关键部分
        if turn["type"] == "tool_output" and len(turn["content"]) > max_tool_output_chars:
            head = turn["content"][: max_tool_output_chars // 2]
            tail = turn["content"][-max_tool_output_chars // 2:]
            turn = {**turn, "content": f"{head}\n...[已截断]...\n{tail}"}

        trimmed.append(turn)

    return trimmed

